"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["46815"],{95237(e){e.exports=JSON.parse('{"id":"F296","slug":"tips-inflation-adjustment","name":"Inflation-Linked Bond (TIPS) Cash Flows and Breakeven Inflation","subject":"Fixed Income","section":"Bonds","topic":"Inflation-linked bonds","level":"Intermediate","aliases":["TIPS","index linked gilt","real return bond","inflation protected","breakeven inflation"],"formula":{"latex":"\\\\text{Adjusted principal}=F\\\\times\\\\frac{CPI_{t}}{CPI_{0}},\\\\quad \\\\text{Coupon}=\\\\text{Adjusted principal}\\\\times\\\\frac{c}{m},\\\\quad BE=\\\\frac{1+y_{nom}}{1+y_{real}}-1","also":[],"text":"Adjusted principal = Face x CPI now / CPI at issue; Coupon = Adjusted principal x real coupon rate / payments per year; Breakeven inflation = (1 + nominal yield) / (1 + real yield) - 1"},"symbols":[{"symbol":"F","meaning":"Original face value","unit":"money"},{"symbol":"CPI_t, CPI_0","meaning":"Consumer price index now and at issue","unit":"number"},{"symbol":"c","meaning":"Real coupon rate, fixed at issue","unit":"per year"},{"symbol":"y_nom, y_real","meaning":"Yields on a nominal bond and an inflation-linked bond of the same maturity","unit":"per year"},{"symbol":"BE","meaning":"Breakeven inflation, the rate at which both bonds earn the same","unit":"per year"}],"when_to_use":"Use it to see what an inflation-linked bond pays. The principal is scaled up by inflation, and the coupon is a fixed rate applied to that higher principal, so both rise with prices. Breakeven inflation shows the inflation rate the market is pricing in.","worked_example":{"problem":"A 1,000 inflation-linked bond with a 1.5% real coupon paid twice a year was issued when the CPI was 250. The CPI is now 262.5. A nominal bond of the same maturity yields 4.2% while the inflation-linked bond yields 1.8% in real terms. What does it pay and what inflation is priced in?","inputs":{"face":1000,"c":1.5,"cpi0":250,"cpi1":262.5,"m":2,"nom":4.2,"real":1.8},"steps":[{"label":"Inflation since issue = CPI now / CPI at issue - 1","working":"262.5 / 250-1","value":"5.00%"},{"label":"Adjusted principal = face x CPI now / CPI at issue","working":"1000 x 262.5 / 250","value":"1,050.00"},{"label":"Coupon = adjusted principal x c / m","working":"1050 x 0.015 / 2","value":"7.88"},{"label":"Breakeven inflation = (1 + nominal) / (1 + real) - 1","working":"(1+0.042) / (1+0.018)-1","value":"2.36%"}],"answer":"Prices are up 5.00% since issue, so the principal is now 1,050.00 and each coupon is 7.88. Breakeven inflation is 2.36%. If inflation averages more than that, the inflation-linked bond does better."},"calculator":{"available":true,"inputs":[{"id":"face","label":"Original face value","unit":"money","type":"number","default":1000,"hint":""},{"id":"c","label":"Real coupon rate","unit":"%","type":"number","default":1.5,"hint":""},{"id":"cpi0","label":"CPI at issue","unit":"number","type":"number","default":250,"hint":""},{"id":"cpi1","label":"CPI now","unit":"number","type":"number","default":262.5,"hint":""},{"id":"m","label":"Payments per year","unit":"number","type":"number","default":2,"hint":"","min":1},{"id":"nom","label":"Nominal bond yield","unit":"%","type":"number","default":4.2,"hint":""},{"id":"real","label":"Inflation-linked bond real yield","unit":"%","type":"number","default":1.8,"hint":""}],"checks":[],"steps":[{"id":"infl","label":"Inflation since issue = CPI now / CPI at issue - 1","expr":"cpi1/cpi0-1","format":"pct2"},{"id":"adj","label":"Adjusted principal = face x CPI now / CPI at issue","expr":"face*cpi1/cpi0","format":"money"},{"id":"cpn","label":"Coupon = adjusted principal x c / m","expr":"adj*c/m","format":"money"},{"id":"be","label":"Breakeven inflation = (1 + nominal) / (1 + real) - 1","expr":"(1+nom)/(1+real)-1","format":"pct2"}],"results":["adj","cpn","be"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"infl":0.05,"adj":1050,"cpn":7.875,"be":2.3575638506876162e-2}},"finder":{"finds":"Cash flows of an inflation-linked bond and priced-in inflation","needs":"Face value, real coupon, CPI levels, yields"},"related":[{"slug":"real-return","name":"Real Return (Inflation-Adjusted)"},{"slug":"purchasing-power","name":"Purchasing Power of Money Over Time"},{"slug":"bond-price","name":"Bond Price"}],"related_ids":["F036","F035","F284"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Adjusted\xa0principal</mtext><mo>=</mo><mi>F</mi><mo>\xd7</mo><mfrac><mrow><mi>C</mi><mi>P</mi><msub><mi>I</mi><mi>t</mi></msub></mrow><mrow><mi>C</mi><mi>P</mi><msub><mi>I</mi><mn>0</mn></msub></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Coupon</mtext><mo>=</mo><mtext>Adjusted\xa0principal</mtext><mo>\xd7</mo><mfrac><mi>c</mi><mi>m</mi></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>B</mi><mi>E</mi><mo>=</mo><mfrac><mrow><mn>1</mn><mo>+</mo><msub><mi>y</mi><mrow><mi>n</mi><mi>o</mi><mi>m</mi></mrow></msub></mrow><mrow><mn>1</mn><mo>+</mo><msub><mi>y</mi><mrow><mi>r</mi><mi>e</mi><mi>a</mi><mi>l</mi></mrow></msub></mrow></mfrac><mo>\u2212</mo><mn>1</mn></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Adjusted principal}=F\\\\times\\\\frac{CPI_{t}}{CPI_{0}},\\\\quad \\\\text{Coupon}=\\\\text{Adjusted principal}\\\\times\\\\frac{c}{m},\\\\quad BE=\\\\frac{1+y_{nom}}{1+y_{real}}-1</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"tracking-difference","name":"Index Fund Tracking Difference and Error"},"next":{"slug":"information-ratio","name":"Information Ratio and Tracking Error"},"lesson":null,"total":522}')}}]);